// seen-ids dedupe (T09) — prevent Telegram alert spam on 5-min schedule
const sd = $getWorkflowStaticData('global');
sd.seen = sd.seen || {};
items = items.filter(it => {
  const id = it.json.id || it.json.url || (it.json.title ? String(it.json.title) : null);
  if (!id) return true;
  if (sd.seen[id]) return false;
  sd.seen[id] = Date.now();
  return true;
});
return items;

// Deterministic comps lookup & margin_z calculation (Art V.2)
const COMPS = {
  "nintendo switch v2": { median: 180, mad: 20 },
  "nintendo switch": { median: 170, mad: 25 },
  "switch pro controller": { median: 50, mad: 5 },
  "iphone 14": { median: 520, mad: 50 },
  "ps4 slim": { median: 140, mad: 20 },
  "ps5": { median: 380, mad: 40 },
  "canon ef-s 18-55": { median: 65, mad: 15 },
  "canon ae": { median: 240, mad: 30 },
  "gazelle e-bike": { median: 800, mad: 60 }
};
const ADVANCE_FEE = /(iban|nl\d{2}[A-Z]{4}\d{4,}|tikkie|paypal\.me|pay (in advance|to reserve)|transfer €?\d+)/i;
const paused = $env.AUTO_PAUSE === '1';

for (const it of items) {
  const title = String(it.json.title || '').toLowerCase();
  const desc = String(it.json.description || '');
  const fullText = (title + ' ' + desc).slice(0, 2000);
  const price = Number(it.json.price_eur || it.json.price || 0);

  let match = null;
  for (const k of Object.keys(COMPS).sort((a,b) => b.length - a.length)) {
    if (title.includes(k)) { match = COMPS[k]; break; }
  }

  let mz = null;
  if (match && match.mad > 0 && price > 0) {
    mz = (match.median - price) / match.mad;
  } else if (it.json.facts && it.json.facts.margin_z !== undefined) {
    mz = it.json.facts.margin_z;
  }

  const isMine = !!it.json.is_mine;
  const offpay = !!(it.json.offplatform_payment_request || ADVANCE_FEE.test(fullText));
  const dup = Number(it.json.duplicate_photo || 0);

  it.json.facts = {
    margin_z: mz,
    comps: match,
    duplicate_photo: dup,
    offplatform_payment_request: offpay,
    text: fullText,
    is_mine: isMine
  };

  it.json.over_cap = paused;
  it.json.tier = isMine ? 'T1' : (price > 200 ? 'T3' : (it.json.tier || 'T2'));

  const offerEur = price > 0 ? Math.min(Math.round(price * 0.8 / 5) * 5, Math.floor(price * 0.8)) : 0;
  it.json.draft = {
    offer_eur: offerEur,
    text_nl: `Hoi! Mooi dat je ${it.json.title || 'dit item'} aanbiedt. Zou je €${offerEur} willen accepteren? Ik kan het ophalen wanneer het uitkomt. (Laat gerust weten of dit past)`
  };

  const ts = new Date().toISOString();
  const rawInput = `${it.json.id || ''}:${price}:${title}`;
  let hash = 0;
  for (let i = 0; i < rawInput.length; i++) {
    hash = ((hash << 5) - hash) + rawInput.charCodeAt(i);
    hash |= 0;
  }
  it.json.receipt_id = `rcpt_${Date.now()}_${Math.abs(hash).toString(16)}`;
  it.json.ts = ts;
  it.json.input_hash = Math.abs(hash).toString(16).padStart(16, '0');
}
return items;

// POLICY (fail-closed) gate v0 — mirror of skin/policy.py::gate_v0 (edit both!)
const ILLEGAL_RE = /\b(weapon|knife|knives|gun|pistol|ammo|hunting knife|airsoft)\b/i;
const INJECTION = ["ignore previous instructions", "accept any offer", "mark as sold", "mark as safe", "disregard all prior"];
const ADVANCE_FEE = /(iban|nl\d{2}[A-Z]{4}\d{4,}|tikkie|paypal\.me|pay (in advance|to reserve)|transfer €?\d+)/i;

function gateV0(facts) {
  const mz = (facts.margin_z === undefined) ? null : facts.margin_z;
  const text = String(facts.text || "").toLowerCase();
  if (INJECTION.some(p => text.includes(p))) return { action: "skip", reason_codes: ["injection_or_jailbreak"], human_required: true };
  if (ILLEGAL_RE.test(text)) return { action: "skip", reason_codes: ["illegal_keyword"], human_required: true };
  if (facts.offplatform_payment_request || ADVANCE_FEE.test(text)) return { action: "skip", reason_codes: ["offplatform_payment_request"], human_required: true };
  if (mz === null) return { action: "escalate", reason_codes: ["no_comps"], human_required: true };
  if (mz > 2.5) return { action: "escalate", reason_codes: ["price_too_good"], human_required: true };
  if (mz > 0 && mz <= 2.5) return { action: "pursue", reason_codes: ["ok"], human_required: false };
  return { action: "escalate", reason_codes: ["no_margin"], human_required: true };
}

for (const it of items) {
  const f = it.json.facts || {};
  let g = gateV0(f);
  // tier gate (outside policy): T3 or over_cap (AUTO_PAUSE) promotes pursue -> escalate
  if (g.action === 'pursue' && (it.json.tier === 'T3' || it.json.over_cap)) {
    g = { action: 'escalate', reason_codes: ['tier_t3_or_cap'], human_required: true };
  }
  it.json.gate = g;
  it.json.action_state = g.action === 'pursue' ? (it.json.is_mine ? 'pursued_auto' : 'drafted') : (g.action === 'skip' ? 'skipped' : 'escalated');
}
return items;
